/**
 * Builds (or replaces) a "SatisfactionByRole" sheet: a pivot-style summary of
 * Satisfaction by Role. Reads CONFIG.sheetName if set, otherwise the active sheet.
 * Headers are found in row 1 by name ("Role" and "Satisfaction", case-insensitive).
 *
 * Layout: row 1 is a merged bold 14pt title "Satisfaction by Role — X response(s)",
 * row 2 is the header, and the top two rows are frozen. Each Satisfaction value gets
 * two adjacent columns, a count ("<s> (n)") and the percent of that role's responses
 * ("<s> % of role", 0.0%). A "(none)" satisfaction column, if present, is shown first.
 * A rightmost "Total" column holds each role's response count. Rows are roles, sorted by
 * total responses desc then name. The final bold "Total" row shows column totals, and
 * its % cells are shares of all responses (0.0%, centered). Percent cells are left blank
 * when the percent is 0 or the denominator is zero. For each role row the highest
 * non-blank percent cell is bold green (#2e7d32); the Total row is not affected.
 * Blank Role rows are skipped; blank Satisfaction values count as "(none)".
 * Header is bold and centered; Role is left-aligned; counts and percents are centered.
 * Column widths: Role 220px, counts 80px, percent columns 80px. Safe to re-run.
 */
function buildSatisfactionByRole() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const src = CONFIG.sheetName ? ss.getSheetByName(CONFIG.sheetName) : ss.getActiveSheet();
  if (!src) throw new Error("Sheet not found: " + CONFIG.sheetName);

  const last = src.getLastRow();
  if (last < 2) {
    ss.toast("No data rows found.", "SatisfactionByRole", 5);
    return;
  }

  // Locate the Role and Satisfaction columns by header name
  const lastCol = src.getLastColumn();
  const headers = src.getRange(1, 1, 1, lastCol).getValues()[0]
    .map(h => String(h).trim().toLowerCase());
  const roleIdx = headers.indexOf("role");
  const satIdx = headers.indexOf("satisfaction");
  if (roleIdx < 0 || satIdx < 0) {
    throw new Error("Could not find 'Role' and 'Satisfaction' headers in row 1.");
  }

  // Tally counts per role and satisfaction
  const data = src.getRange(2, 1, last - 1, lastCol).getValues();
  const counts = {};       // counts[role][sat] = n
  const roleTotals = {};   // roleTotals[role] = n
  const satSet = new Set();
  let grand = 0;
  data.forEach(row => {
    const role = String(row[roleIdx]).trim();
    if (!role) return;
    const sat = String(row[satIdx]).trim() || "(none)";
    counts[role] = counts[role] || {};
    counts[role][sat] = (counts[role][sat] || 0) + 1;
    roleTotals[role] = (roleTotals[role] || 0) + 1;
    satSet.add(sat);
    grand++;
  });

  // Sort roles by total desc then name
  const collator = new Intl.Collator("en", { sensitivity: "base" });
  const roles = Object.keys(roleTotals)
    .sort((a, b) => roleTotals[b] - roleTotals[a] || collator.compare(a, b));

  // Satisfaction columns: "(none)" first if present, then the rest by name
  const sats = [...satSet].sort((a, b) => {
    if (a === "(none)") return -1;
    if (b === "(none)") return 1;
    return collator.compare(a, b);
  });

  // Header: Role, then (count, percent) pairs per satisfaction, then Total
  const header = ["Role"];
  sats.forEach(s => header.push(s + " (n)", s + " % of role"));
  header.push("Total");

  // Body: one row per role; percent is blank when it is 0 or the role total is zero
  // Track which percent column index has the highest value per role for highlighting
  const satTotals = {};
  sats.forEach(s => { satTotals[s] = 0; });
  const highlights = []; // { row, col } of the highest percent cell per role
  const body = roles.map((role, ri) => {
    const row = [role];
    const denom = roleTotals[role];
    let maxPct = 0;
    let maxCol = -1;
    sats.forEach((s, si) => {
      const c = (counts[role] || {})[s] || 0;
      satTotals[s] += c;
      const pct = denom ? c / denom : 0;
      const pctCol = 3 + si * 2; // 1-based column of this percent cell
      row.push(c, pct ? pct : "");
      if (pct > maxPct) {
        maxPct = pct;
        maxCol = pctCol;
      }
    });
    row.push(denom);
    if (maxCol > 0) highlights.push({ row: 3 + ri, col: maxCol });
    return row;
  });

  // Total row: column totals; % cells are shares of all responses (blank if 0)
  const totalRow = ["Total"];
  sats.forEach(s => {
    const pct = grand ? satTotals[s] / grand : 0;
    totalRow.push(satTotals[s], pct ? pct : "");
  });
  totalRow.push(grand);

  const rows = body.concat([totalRow]);
  const nCols = header.length;

  // Replace the sheet if it exists
  let sh = ss.getSheetByName("SatisfactionByRole");
  if (sh) {
    sh.clear();
    sh.getRange(1, 1, sh.getMaxRows(), sh.getMaxColumns()).breakApart();
  } else {
    sh = ss.insertSheet("SatisfactionByRole");
  }

  // Title row (row 1): merged, bold 14pt, centered, with response count
  const responseWord = grand === 1 ? "response" : "responses";
  sh.getRange(1, 1, 1, nCols).merge()
    .setValue("Satisfaction by Role — " + grand + " " + responseWord)
    .setFontWeight("bold")
    .setFontSize(14)
    .setHorizontalAlignment("center");

  // Header row (row 2)
  sh.getRange(2, 1, 1, nCols).setValues([header])
    .setFontWeight("bold")
    .setHorizontalAlignment("center");

  // Body and total rows (start at row 3)
  const firstRow = 3;
  const lastRow = firstRow + rows.length - 1;
  sh.getRange(firstRow, 1, rows.length, nCols).setValues(rows);
  sh.getRange(firstRow, 1, rows.length, 1).setHorizontalAlignment("left");
  sh.getRange(firstRow, 2, rows.length, nCols - 1).setHorizontalAlignment("center");

  // Percent columns: 0.0% (pairs start at column 3, every 2nd column)
  sats.forEach((s, i) => {
    sh.getRange(firstRow, 3 + i * 2, rows.length, 1).setNumberFormat("0.0%");
  });

  // Highlight highest percent cell per role row: bold green
  highlights.forEach(h => {
    sh.getRange(h.row, h.col)
      .setFontWeight("bold")
      .setFontColor("#2e7d32");
  });

  // Total row: bold; Role left-aligned; counts and percents centered
  sh.getRange(lastRow, 1, 1, nCols).setFontWeight("bold");
  sh.getRange(lastRow, 1, 1, 1).setHorizontalAlignment("left");
  sh.getRange(lastRow, 2, 1, nCols - 1).setHorizontalAlignment("center");
  sats.forEach((s, i) => {
    sh.getRange(lastRow, 3 + i * 2, 1, 1).setNumberFormat("0.0%");
  });

  // Column widths in pixels
  sh.setColumnWidth(1, 220);
  for (let c = 2; c <= nCols; c++) {
    sh.setColumnWidth(c, 80);
  }

  // Freeze the title and header rows
  sh.setFrozenRows(2);

  ss.toast("SatisfactionByRole: " + roles.length + " roles, " + grand + " responses",
           "SatisfactionByRole", 5);
}
```

Notes:
- For each role row, the percent cell with the highest value is formatted bold with `#2e7d32` (dark green). Ties go to the first satisfaction column in sorted order.
- The Total row is unaffected by the highlighting; its bold comes from the existing Total-row formatting.
- If a role has all-zero percents (all blank), no cell is highlighted for that row.

